  ui_story_31990601_18_dialog_content = "...",
  ui_story_31990601_19_dialog_content = "Eu realmente sou esse tipo de pessoa aos seus olhos, PlayerName?",
  ui_story_31990601_20_dialog_content = "A Rediesel Wrench pode não ter estrutura e disciplina, mas isso não os torna Eclipsitas. Como tal, não tenho motivo para apontar minha arma para eles.",
  ui_story_31990601_21_dialog_content = "E-Então... Por que você está realmente aqui?",
  ui_story_31990601_22_dialog_content = "Eu não estava mentindo para você. Eu realmente estou em uma missão de observação... Eu só fiz um pequeno desvio, só isso.",
  ui_story_31990601_23_dialog_content = "Originalmente, eu pretendia fazer uma pesquisa na área entre as linhas de frente e o deserto, mas acabei perto do acampamento da Rediesel Wrench sem nem perceber.",
  ui_story_31990601_24_dialog_content = "Eu não ia ficar muito tempo, mas o Deserto Rediesel parece ter um certo charme...",
  ui_story_31990601_25_dialog_content = "Dirigi por dois dias, tentando sair, apenas para me encontrar exatamente onde comecei.",
  ui_story_31990601_26_dialog_content = "...",
  ui_story_31990601_27_dialog_content = "Isso só parece que você se perdeu!!!",
  ui_story_31990601_28_dialog_content = "Não estou perdido. Estou apenas executando o Plano de Contingência #43, só isso.",
  ui_story_31990601_29_dialog_content = "Tem certeza de que não está apenas inventando isso?!",
  ui_story_31990601_30_dialog_content = "De maneira nenhuma. Na verdade, é a solução ideal, dado que um elfo do deserto tem me trazido comida todo esse tempo.",
  ui_story_31990601_31_dialog_content = "Com a ajuda dela, posso executar o Plano de Contingência #43 sem me preocupar com restrições de tempo.",
  ui_story_31990601_32_dialog_content = "Espera, espera, espera!",
  ui_story_31990601_33_dialog_content = "O que é um elfo do deserto?!",
