  ui_story_31990601_35_dialog_content = "Então isso significa...",
  ui_story_31990601_36_dialog_content = "Você está apenas sobrevivendo aqui porque tem se aproveitado das reservas de comida da Rediesel Wrench!",
  ui_story_31990601_37_dialog_content = "Como eu disse, eles eram presentes de um elfo do deserto e não do Rediesel...",
  ui_story_31990601_38_dialog_content = "Aí está você, Senhorita Pokerface!",
  ui_story_31990601_39_dialog_content = "Isso...",
