  ui_story_31990601_45_dialog_content = "Er... Sim, isso mesmo! Na verdade, estou viajando com a senhorita Pokerface aqui!",
  ui_story_31990601_46_dialog_content = "Como eu disse antes, eu não sou um viajante. O Deserto Rediesel é minha casa.",
