  ui_story_31990601_48_dialog_content = "Se for esse o caso, então você vai adorar o almoço de hoje! Tcharam!",
  ui_story_31990601_49_dialog_content = "Lagartos de pimenta fantasma extra-picante!",
  ui_story_31990601_50_dialog_content = "Lá está... A verdadeira razão pela qual todos se afastam do Deserto Rediesel!",
  ui_story_31990601_51_dialog_content = "<size=30>Isso... é realmente para ser comido? Como eu pensei, este lugar é para ser temido... Mas...</size>",
  ui_story_31990601_52_dialog_content = "Obrigado. Como nativo do Deserto Rediesel, naturalmente amo esta iguaria local.",
  ui_story_31990601_53_dialog_content = "Seu presente é muito apreciado. Mal posso esperar para comer este prato maravilhoso.",
