  ui_story_31990601_55_dialog_content = "Eu... Eu acho que um é mais do que suficiente.",
  ui_story_31990601_56_dialog_content = "Hum... Se você não tem certeza de como comer, posso te dar algumas dicas...",
  ui_story_31990601_57_dialog_content = "Claro, eu sei como comer isso. Como eu disse, eu sou nativo do Deserto Rediesel.",
  ui_story_31990601_58_dialog_content = "Gole!",
