  ui_story_31990601_76_dialog_content = "Por que não levamos o resto desses lagartos pimenta-fantasma para casa como nossas lembranças?!",
  ui_story_31990601_77_dialog_content = "Ah, não seja tão educado, eu poderia simplesmente dar isso a você como um presente.",
  ui_story_31990601_78_dialog_content = "Mas não parece que a Senhorita Pokerface comeu o suficiente ainda...",
