  ui_story_31990601_80_dialog_content = "O-Claro que ela faz! É só...",
  ui_story_31990601_81_dialog_content = "Temos uma viagem tão longa para casa, e ela pode passar mal na volta se comer demais.",
  ui_story_31990601_82_dialog_content = "É por isso...",
